import React, { useState, useEffect } from 'react';
import { useWidgetDraggable, useWidgetResizable, useWidgetPersistence, useWidgetAI } from '../hooks/useWidgetHooks';
import '../styles/NewsWidget.css';

const NewsWidget = () => {
  const widgetId = 'news-widget';
  const draggable = useWidgetDraggable(widgetId);
  const resizable = useWidgetResizable(widgetId);
  const { data: newsData, updateData } = useWidgetPersistence(widgetId, {
    headlines: [],
    searchHistory: [],
    category: 'general',
  });
  const { callGemini, loading: aiLoading } = useWidgetAI();

  const [activeTab, setActiveTab] = useState('headlines');
  const [newsHeadlines, setNewsHeadlines] = useState(newsData.headlines || []);
  const [searchHistory, setSearchHistory] = useState(newsData.searchHistory || []);
  const [selectedCategory, setSelectedCategory] = useState('general');
  const [aiSummaries, setAiSummaries] = useState({});

  // Fetch news
  const fetchNews = async (query = 'latest') => {
    try {
      const apiKey = process.env.REACT_APP_NEWS_API_KEY || 'demo';
      const newsUrl = `https://newsapi.org/v2/everything?q=${query}&sortBy=publishedAt&language=en&apiKey=${apiKey}`;

      const response = await fetch(newsUrl);
      if (!response.ok) throw new Error('Failed to fetch news');

      const data = await response.json();
      const formattedNews = data.articles.slice(0, 10).map((article, idx) => ({
        id: idx,
        headline: article.title,
        summary: article.description,
        source: article.source.name,
        time: new Date(article.publishedAt).toLocaleTimeString(),
        image: article.urlToImage,
        url: article.url,
        category: selectedCategory,
      }));

      setNewsHeadlines(formattedNews);
      updateData((prev) => ({ ...prev, headlines: formattedNews }));

      // Add to search history
      const historyItem = {
        query,
        date: new Date().toLocaleTimeString(),
        preview: formattedNews[0]?.headline || query,
      };
      const newHistory = [historyItem, ...searchHistory].slice(0, 20);
      setSearchHistory(newHistory);
      updateData((prev) => ({ ...prev, searchHistory: newHistory }));
    } catch (error) {
      console.error('News fetch error:', error);
    }
  };

  // AI Summarize news item
  const summarizeNews = async (headline) => {
    const prompt = `Summarize this news headline in 2-3 sentences, focusing on key information:

"${headline}"

Keep it concise and factual.`;

    const result = await callGemini(prompt);
    if (result.success) {
      setAiSummaries((prev) => ({
        ...prev,
        [headline]: result.content,
      }));
    }
  };

  // AI Categorize and analyze trends
  const analyzeTrends = async () => {
    const headlines = newsHeadlines.map((n) => n.headline).join('\n');
    const prompt = `Analyze these news headlines and identify main trends and categories:

${headlines}

Provide:
1. Main trending topics (top 3)
2. Sentiment analysis (positive/negative/neutral)
3. Key focus areas
4. Predicted impact

Keep response concise.`;

    const result = await callGemini(prompt);
    if (result.success) {
      alert('Trend Analysis:\n\n' + result.content);
    }
  };

  useEffect(() => {
    fetchNews();
  }, []);

  return (
    <div
      {...draggable}
      ref={draggable.ref}
      {...resizable}
      className="widget-container news-widget"
      style={{
        ...draggable.style,
        ...resizable.style,
        position: 'fixed',
        zIndex: 1000,
        backgroundColor: '#0a0e27',
        border: '2px solid #00ff88',
        borderRadius: '8px',
        boxShadow: '0 0 20px rgba(0, 255, 136, 0.3)',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      {/* Header */}
      <div className="widget-header" style={{ borderBottom: '2px solid #00ff88', padding: '12px' }}>
        <div className="widget-title" style={{ color: '#00ff88', fontSize: '16px', fontWeight: 'bold' }}>
          📰 NEWS WIDGET
        </div>
        <div className="widget-status" style={{ fontSize: '11px', color: '#00aa66' }}>
          ● LIVE FEED ACTIVE
        </div>
      </div>

      {/* Tabs */}
      <div className="news-tabs" style={{ display: 'flex', borderBottom: '1px solid #00ff88', gap: '10px', padding: '8px' }}>
        {['headlines', 'trending', 'history'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            style={{
              background: activeTab === tab ? '#00ff88' : 'transparent',
              color: activeTab === tab ? '#0a0e27' : '#00ff88',
              border: '1px solid #00ff88',
              padding: '6px 12px',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '12px',
              fontWeight: activeTab === tab ? 'bold' : 'normal',
            }}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </div>

      {/* Content Area */}
      <div
        className="news-content"
        style={{
          flex: 1,
          overflowY: 'auto',
          padding: '12px',
          color: '#00ff88',
          fontSize: '12px',
        }}
      >
        {activeTab === 'headlines' && (
          <div className="news-headlines">
            <input
              type="text"
              placeholder="Search news..."
              onChange={(e) => e.target.value && fetchNews(e.target.value)}
              style={{
                width: '100%',
                padding: '8px',
                marginBottom: '10px',
                backgroundColor: '#1a1f3a',
                border: '1px solid #00ff88',
                color: '#00ff88',
                borderRadius: '4px',
              }}
            />
            {newsHeadlines.map((news) => (
              <div key={news.id} className="news-item" style={{ marginBottom: '12px', borderBottom: '1px solid #00ff8833', paddingBottom: '10px' }}>
                <div style={{ fontWeight: 'bold', color: '#00ffff' }}>{news.headline}</div>
                <div style={{ fontSize: '11px', color: '#00aa66', margin: '4px 0' }}>
                  {news.source} · {news.time}
                </div>
                <div style={{ fontSize: '11px', color: '#cccccc', margin: '4px 0' }}>{news.summary}</div>
                <button
                  onClick={() => summarizeNews(news.headline)}
                  style={{
                    background: '#00ff8833',
                    border: '1px solid #00ff88',
                    color: '#00ff88',
                    padding: '4px 8px',
                    borderRadius: '3px',
                    fontSize: '10px',
                    cursor: 'pointer',
                    marginTop: '4px',
                  }}
                >
                  {aiLoading ? 'Analyzing...' : 'AI Summary'}
                </button>
                {aiSummaries[news.headline] && (
                  <div style={{ fontSize: '10px', color: '#ffff00', marginTop: '6px', backgroundColor: '#1a1f3a', padding: '6px', borderRadius: '3px' }}>
                    <strong>AI Summary:</strong> {aiSummaries[news.headline]}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {activeTab === 'trending' && (
          <div className="trending-analysis">
            <button
              onClick={analyzeTrends}
              style={{
                width: '100%',
                padding: '10px',
                background: '#00ff88',
                color: '#0a0e27',
                border: 'none',
                borderRadius: '4px',
                fontWeight: 'bold',
                cursor: 'pointer',
                marginBottom: '10px',
              }}
            >
              {aiLoading ? 'Analyzing...' : 'Analyze Trends'}
            </button>
          </div>
        )}

        {activeTab === 'history' && (
          <div className="search-history">
            {searchHistory.length === 0 ? (
              <div style={{ color: '#00aa66' }}>No search history</div>
            ) : (
              searchHistory.map((item, idx) => (
                <div key={idx} style={{ marginBottom: '8px', borderBottom: '1px solid #00ff8833', paddingBottom: '8px' }}>
                  <div style={{ fontWeight: 'bold' }}>{item.query}</div>
                  <div style={{ fontSize: '10px', color: '#00aa66' }}>{item.date}</div>
                  <div style={{ fontSize: '11px', color: '#cccccc' }}>{item.preview}</div>
                </div>
              ))
            )}
          </div>
        )}
      </div>

      {/* Resize Handle */}
      <div
        onMouseDown={resizable.onResizeStart}
        style={{
          width: '20px',
          height: '20px',
          position: 'absolute',
          bottom: '0',
          right: '0',
          cursor: 'nwse-resize',
          background: 'linear-gradient(135deg, transparent 50%, #00ff88 50%)',
          borderRadius: '0 0 8px 0',
        }}
      />
    </div>
  );
};

export default NewsWidget;
